window.docContents[25].resolve({"/Gamma-Function/___5___11-Asymptotic-Expansions/#LMLF-___-DLMF-with-Lean--Gamma-Function--___5___11-Asymptotic-Expansions--___5___11_LPAR_i_RPAR_-Poincar___-Type-Expansions":{"contents":"As z\\to\\infty in |\\operatorname{ph}z|\\le\\pi-\\delta,\n\\operatorname{Ln}\\Gamma(z)\\sim\n\\left(z-\\frac12\\right)\\ln z-z+\\frac12\\ln(2\\pi)\n+\\sum_{k=1}^{\\infty}\\frac{B_{2k}}{2k(2k-1)z^{2k-1}}.For positive real x, the Lean specialization uses the same Bernoulli terms. After any finite\ntruncation, the remaining error is little-o of the last retained term as x tends to infinity.The distinct finite theorem says that the remainder has the sign of the first omitted term and no\ngreater magnitude.\n\n","context":"LMLF · DLMF with Lean\u0009Gamma Function\u0009§5.11 Asymptotic Expansions","header":"§5.11(i) Poincaré-Type Expansions","id":"/Gamma-Function/___5___11-Asymptotic-Expansions/#LMLF-___-DLMF-with-Lean--Gamma-Function--___5___11-Asymptotic-Expansions--___5___11_LPAR_i_RPAR_-Poincar___-Type-Expansions"}});